// intent: Exercises iterative CBOR and MessagePack writers with custom keys to ensure write_cbor_key and write_msgpack_key are invoked iteratively.
#include <nlohmann/json.hpp>
#include <map>
#include <string>
#include <iostream>

struct iter_key {
    std::string s;
    bool operator<(const iter_key& o) const { return s < o.s; }
    operator std::string() const { return s; }
};

using iter_map = std::map<iter_key, nlohmann::json, std::less<iter_key>>;
using iter_json = nlohmann::basic_json<iter_map>;

int main() {
    iter_json j;
    j[iter_key{"k1"}] = 10;
    j[iter_key{"k2"}] = 20;
    auto cbor = iter_json::to_cbor(j);
    auto msgpack = iter_json::to_msgpack(j);
    std::cout << "Iterative CBOR bytes: " << cbor.size() << ", MsgPack bytes: " << msgpack.size() << std::endl;
    return 0;
}
